74	// gitCommitRefExists reports whether ref resolves to a commit in the current
75	// repo. Local and best-effort: any error reads as "absent".
76	func gitCommitRefExists(ctx context.Context, ref string) bool {
77		return exec.CommandContext(ctx, "git", "rev-parse", "--verify", "--quiet", ref+"^{commit}").Run() == nil
78	}
